(async()=>{const root=document.getElementById('report-content');try{Auth.init();window.opener=null;if(!Auth.isLoggedIn||Auth.currentUser?.needPasswordChange){root.textContent='请先在主系统登录，再打开报告。';return;}await Auth.loadOperationsRollout();if(!Auth.canReadOperationsReports()){root.textContent='当前账号无报告阅读权限。';return;}await OperationsReportCenter.readReport();}catch(e){root.textContent=e.message;}})();
